  const m = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/.exec(text);
  if (text === "" || m === null || (m[1] === undefined && m[2] === undefined && m[3] === undefined)) {
    throw new RangeError(`not a duration: ${JSON.stringify(text)}`);
  }
  const [h, min, s] = [m[1], m[2], m[3]].map((v): number => (v === undefined ? 0 : Number(v)));
  return h * 3600 + min * 60 + s;
}

